import { Component, h, Prop, ComponentInterface, Host } from '@stencil/core';
import classnames from 'classnames';
import { StatusIconVariant } from '@src/components/ks-status-icon/types';
import { KsIconRefresh } from '@fe-infra/keystone-icons-stencil';

const prefix = 'status-message';

/**
 * @slot default - Status text rendered when `richTextString` is not provided.
 */
@Component({
  tag: 'ks-status-message',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsStatusMessage implements ComponentInterface {
  /** Defines the visual variant of the status message. Can be one of the following values: `"neutral"`, `"success"`, `"warning"` or `"error"`. */
  @Prop() variant: Exclude<
    StatusIconVariant,
    'info' | 'suggestion' | 'inProgress' | 'successLow' | 'disapproval' | 'limitedApproval'
  > = 'neutral';
  /**
   * To render text by passing a rich text string, it currently only supports parsing <a> tags in the text,
   * such as `You can <a href="help.com">learn more</a>.`
   */
  @Prop() richTextString = '';

  /** An optional call-to-action button rendered alongside the status message. Provide a `label` for the button text and an `onClick` handler. */
  @Prop() cta?: { label: string; onClick: () => void };

  render() {
    const cls = classnames(prefix);
    return (
      <Host class="KsStatusMessage">
        <div class={cls} role="status">
          <ks-status-icon class={`${prefix}__icon`} variant={this.variant} size={'sm'}></ks-status-icon>
          <ks-text richTextString={this.richTextString} color={this.variant} variant={'labelSm'}>
            {!this.richTextString && <slot></slot>}
          </ks-text>
          {this.cta && (
            <ks-button variant="text" size="xs" onClick={this.cta.onClick} data-testid="ks-status-message-index-1hLFyX">
              <KsIconRefresh size="14" />
              {this.cta.label}
            </ks-button>
          )}
        </div>
      </Host>
    );
  }
}
